// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // Ensure the role is not the timelock admin role to avoid interference, and account is not a proposer
        vm.assume(role != c.TIMELOCK_ADMIN_ROLE());
        vm.assume(!c.hasRole(c.PROPOSER_ROLE(), account));
        vm.assume(role != bytes32(0));

        // Grant the role to account if not DEFAULT_ADMIN_ROLE
        if (!c.hasRole(role, account)) {
            // Use prank to simulate the grant from this contract (which has TIMELOCK_ADMIN_ROLE)
            vm.prank(address(this));
            c.grantRole(role, account);
        }

        // Now prank as account and attempt to cancel a non-existent operation (will revert because not proposer)
        vm.prank(account);
        vm.expectRevert();
        c.cancel(keccak256("test"));

        // After revert, check supportsInterface for ERC165 (0x01ffc9a7)
        bool supportsErc165 = c.supportsInterface(type(IERC165).interfaceId);
        assertTrue(supportsErc165, "supportsInterface must return true for ERC165");
    }
}

