        vm.assume(c.hasRole(c.PROPOSER_ROLE(), address(this)));

        bytes32 computedId = c.hashOperation(target, value, data, predecessor, salt);
        vm.assume(!c.isOperation(computedId));

        c.schedule(target, value, data, predecessor, salt, delay);

        bool supportsErc165 = c.supportsInterface(0x01ffc9a7);

        assertTrue(supportsErc165);
    }
}

