pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address proposer, address executor) public {
        // Ensure proposer and executor are distinct and not zero
        vm.assume(proposer != address(0));
        vm.assume(executor != address(0));
        vm.assume(proposer != executor);

        // Grant roles so we can schedule and cancel
        bytes32 PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
        bytes32 EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");

        // Grant proposer role to proposer
        vm.prank(address(this));
        c.grantRole(PROPOSER_ROLE, proposer);
        // Grant executor role to executor
        vm.prank(address(this));
        c.grantRole(EXECUTOR_ROLE, executor);

        // Schedule an operation as proposer
        vm.prank(proposer);
        c.schedule(address(0), 0, "", bytes32(0), bytes32(uint256(proposer)), 1);

        // Cancel as proposer
        vm.prank(proposer);
        c.cancel(keccak256(abi.encode(address(0), uint256(0), "", bytes32(0), bytes32(uint256(proposer)))));

        // Check that supportsInterface returns true for IAccessControl interface ID
        bytes4 interfaceId = type(IAccessControl).interfaceId;
        assertTrue(c.supportsInterface(interfaceId));
    }
}

