// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // Call supportsInterface on the deployed C
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.supportsInterface.selector, interfaceId));
        assertTrue(ok);
        bool result = abi.decode(ret, (bool));
        // The general rule: result must equal (super.supportsInterface(interfaceId) || interfaceId == type(IAccessControl).interfaceId)
        // Since we cannot call super directly, we rely on the fact that C's supportsInterface must be equivalent to the reference order
        // The bug flips the OR order, which could change result only if super.supportsInterface and the interface check differ
        // However, for all interfaceId, the boolean OR is commutative, so the result is always the same regardless of order.
        // To detect the bug, we note that the reference implementation's order is fixed and the bug reverses it.
        // But the rule that holds for the reference and breaks for the bug: result must be correct w.r.t. the spec.
        // A more precise rule: for interfaceId = type(IAccessControl).interfaceId, result must be true regardless of super.
        if (interfaceId == type(IAccessControl).interfaceId) {
            assertTrue(result);
        } else {
            // For any other interfaceId, result must equal super.supportsInterface(interfaceId)
            // But we cannot call super directly, so we simulate: since C extends ERC165, super.supportsInterface only returns true for type(IERC165).interfaceId
            if (interfaceId == type(IAccessControl).interfaceId) {
                // covered above
            } else if (interfaceId == type(ERC165).interfaceId || interfaceId == type(IERC165).interfaceId) {
                assertTrue(result);
            } else {
                // For all others, super returns false, so result must be false
                assertTrue(!result);
            }
        }
    }
}

