pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address proposer, bytes32 id) public {
        vm.assume(proposer != address(0));
        vm.assume(proposer != address(this));

        // Check if proposer has PROPOSER_ROLE
        bytes32 proposerRole = keccak256("PROPOSER_ROLE");
        bool proposerHasRole = c.hasRole(proposerRole, proposer);

        // Schedule an operation to make id pending
        bytes32 salt = bytes32(uint256(keccak256(abi.encode(id))));
        if (!c.isOperationPending(id)) {
            // We need to schedule it - but only proposer can do that.
            // For simplicity, we can use address(this) as proposer via prank
            vm.prank(address(this));
            try c.schedule(address(this), 0, "", bytes32(0), salt, 1 days) {
                // success
            } catch {
                // if scheduling fails, we cannot test this id
                return;
            }
        }

        // Now test cancel
        vm.prank(proposer);
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));

        // General rule: cancel should succeed if and only if proposer has PROPOSER_ROLE
        assertTrue(success == proposerHasRole);
    }
}

