pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role) public {
        // Get the admin role from the contract (this is the public getter)
        bytes32 adminRole = c.getRoleAdmin(role);
        // The general rule: getRoleAdmin(role) must equal the admin role that was set.
        // In the reference, the admin role for TIMELOCK_ADMIN_ROLE is TIMELOCK_ADMIN_ROLE itself.
        // For any role that was never set, the admin role is default 0x00.
        // For our test, we only know that DEFAULT_ADMIN_ROLE (0x00) has admin role 0x00.
        // To make a general rule that the reference satisfies and the mutant breaks,
        // we use the fact that in the constructor, TIMELOCK_ADMIN_ROLE is set with admin = TIMELOCK_ADMIN_ROLE.
        // So for role = TIMELOCK_ADMIN_ROLE, the reference returns TIMELOCK_ADMIN_ROLE, while the mutant returns 0x00.
        // We'll fuzz over role but assume it's TIMELOCK_ADMIN_ROLE to ensure known behavior.
        vm.assume(role == c.TIMELOCK_ADMIN_ROLE());
        // The rule: getRoleAdmin(role) should equal role itself (since it was self-administered).
        assertTrue(adminRole == role);
    }
}

