pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure id has no timestamp (isOperationPending would be false)
        vm.assume(c.getTimestamp(id) == 0);
        // In reference: isOperationReady returns false because timestamp > _DONE_TIMESTAMP fails
        // In buggy: isOperationReady returns true because timestamp <= block.timestamp (0 <= anything)
        // The buggy version returns true, which would allow execute/cancel etc. on non-existent ops
        bool ready = c.isOperationReady(id);
        assertTrue(!ready, "isOperationReady should return false for non-existent operation");
    }
}
